<?php
/**
 * Site settings for the gallery package. Only settings that the package
 * still reads are offered here.
 *
 * @package fisheye
 * @subpackage functions
 */

require_once( FISHEYE_PKG_CLASS_PATH.'FisheyeGallery.php' );

$formGalleryGeneral = array(
	"fisheye_menu_text" => array(
		'label' => 'Menu Text',
		'note' => 'The name of this package in the site menu.',
		'type' => 'text'
	),
	"liberty_offline_thumbnailer" => array(
		'label' => 'Background Thumbnailer',
		'note' => 'Thumbnails will be queued and regenerated by a background command-line script. For more information, see '.FISHEYE_PKG_PATH.'thumbnailer.php or you can <a href="'.FISHEYE_PKG_URL.'thumbnailer.php">run it manually</a>',
		'type' => 'checkbox'
	),
);
$gBitSmarty->assign('formGalleryGeneral', $formGalleryGeneral);

// What a gallery page shows around the photos
$formGalleryLists = array(
	"fisheye_gallery_hide_modules" => array(
		'label' => 'Hide modules for galleries',
		'note' => 'When viewing a gallery, hide the left and right module columns',
	),
);
$gBitSmarty->assign( 'formGalleryLists',$formGalleryLists );

// What a photo page shows around the photo
$formImageLists = array(
	"fisheye_image_hide_modules" => array(
		'label' => 'Hide modules for photos',
		'note' => 'When viewing a photo, hide the left and right module columns',
	),
);
$gBitSmarty->assign( 'formImageLists', $formImageLists);

// Columns of the gallery list that the center piece and module show
$formGalleryListLists = array(
	"fisheye_list_title" => array(
		'label' => 'Gallery title',
		'note' => 'List the title of the gallery.',
	),
	"fisheye_list_thumbnail" => array(
		'label' => 'Thumbnail',
		'note' => 'Display a small thumbnail associated with a gallery',
	),
	"fisheye_list_user" => array(
		'label' => 'Creator',
		'note' => 'List the name of the user who created the gallery',
	),
	"fisheye_list_hits" => array(
		'label' => 'Hits',
		'note' => 'List number of hits this gallery has received',
	),
	"fisheye_list_created" => array(
		'label' => 'Creation date',
		'note' => 'List the creation date of the gallery',
	),
	"fisheye_list_lastmodif" => array(
		'label' => 'Last modification',
		'note' => 'List date this gallery was last modified',
	),
);
$gBitSmarty->assign('formGalleryListLists', $formGalleryListLists);

$galleryLayouts = FisheyeGallery::getAllLayouts();
$gBitSmarty->assign( 'galleryPaginationTypes', $galleryLayouts );

$sortOptions = array(
	''                      => tra( 'None' ),
	'lc.title_desc'         => tra( 'Image Title' ).  ' - '.tra( 'descending' ),
	'lc.title_asc'          => tra( 'Image Title' ).  ' - '.tra( 'ascending' ),
	'lc.created_desc'       => tra( 'Date Uploaded' ).' - '.tra( 'descending' ),
	'lc.created_asc'        => tra( 'Date Uploaded' ).' - '.tra( 'ascending' ),
	'lc.last_modified_desc' => tra( 'Last Modified' ).' - '.tra( 'descending' ),
	'lc.last_modified_asc'  => tra( 'Last Modified' ).' - '.tra( 'ascending' ),
);
$gBitSmarty->assign( 'sortOptions', $sortOptions );
$imageSizes = get_image_size_options( FALSE );
$gBitSmarty->assign( 'imageSizes', $imageSizes );

// photos on one page of a gallery before the "more" control
define( 'FISHEYE_PAGE_SIZE_MIN', 12 );
define( 'FISHEYE_PAGE_SIZE_MAX', 500 );

if (!empty($_REQUEST['fisheyeAdminSubmit'])) {
	// General Settings
	foreach ($formGalleryGeneral as $item=>$data) {
		if( $data['type'] == 'checkbox' ) {
			simple_set_toggle($item, FISHEYE_PKG_NAME);
		} elseif( isset( $_REQUEST[$item] ) && is_string( $_REQUEST[$item] ) ) {
			$gBitSystem->storeConfig($item, $_REQUEST[$item], FISHEYE_PKG_NAME );
		}
	}

	foreach( array( $formGalleryLists, $formImageLists, $formGalleryListLists ) as $toggles ) {
		foreach( $toggles as $item => $data ) {
			simple_set_toggle( $item, FISHEYE_PKG_NAME );
		}
	}

	// Each choice is stored only when it is one the form offers
	// An untouched choice is not stored, so a legacy value stays for any older code that shares the settings
	if( isset( $_REQUEST['default_gallery_pagination'] ) && is_string( $_REQUEST['default_gallery_pagination'] ) && isset( $galleryLayouts[$_REQUEST['default_gallery_pagination']] )
		&& $_REQUEST['default_gallery_pagination'] != FisheyeGallery::normalizeLayout( $gBitSystem->getConfig( 'default_gallery_pagination' ) ) ) {
		$gBitSystem->storeConfig( 'default_gallery_pagination', $_REQUEST['default_gallery_pagination'], FISHEYE_PKG_NAME );
	}
	if( isset( $_REQUEST['fisheye_gallery_default_sort_mode'] ) && is_string( $_REQUEST['fisheye_gallery_default_sort_mode'] ) && isset( $sortOptions[$_REQUEST['fisheye_gallery_default_sort_mode']] ) ) {
		$gBitSystem->storeConfig( 'fisheye_gallery_default_sort_mode', $_REQUEST['fisheye_gallery_default_sort_mode'], FISHEYE_PKG_NAME );
	}
	if( isset( $_REQUEST['fisheye_gallery_page_size'] ) && is_numeric( $_REQUEST['fisheye_gallery_page_size'] ) ) {
		$gBitSystem->storeConfig( 'fisheye_gallery_page_size', max( FISHEYE_PAGE_SIZE_MIN, min( FISHEYE_PAGE_SIZE_MAX, (int)$_REQUEST['fisheye_gallery_page_size'] ) ), FISHEYE_PKG_NAME );
	}
	if( !empty( $_REQUEST['default_image_thumbnail_size'] ) && is_string( $_REQUEST['default_image_thumbnail_size'] ) && isset( $imageSizes[$_REQUEST['default_image_thumbnail_size']] ) ) {
		$gBitSystem->storeConfig('fisheye_image_default_thumbnail_size', $_REQUEST['default_image_thumbnail_size'], FISHEYE_PKG_NAME );
	}
}

// assigned after any save above so the form shows the stored value
$gBitSmarty->assign( 'defaultGalleryLayout', FisheyeGallery::normalizeLayout( $gBitSystem->getConfig( 'default_gallery_pagination' ) ) );
$gBitSmarty->assign( 'galleryPageSize', (int)$gBitSystem->getConfig( 'fisheye_gallery_page_size', 60 ) );
